using Spawning;

/// <summary>
/// Authoritative sink for dungeon instability points generated by player actions
/// (PvE enemy defeats and first-time treasure acquisitions) as defined by Document 20 §7-§8.
/// </summary>
public interface IDungeonInstabilitySink
{
    bool TryRecordEnemyDefeat(CreatureTier tier, EnemyPopulationOrigin origin);
    bool TryRecordTreasureFirstAcquisition(string treasureFamily);
}
